try {
  if (ownerForCleanup && deviceIdsForCleanup.length > 0) {
    for (const deviceId of deviceIdsForCleanup.filter((_, index) => index > 0)) {
      await revokeDevice(desktop, ownerForCleanup, deviceId)
    }
    await revokeDevice(desktop, ownerForCleanup, deviceIdsForCleanup[0])
  }
