  await Promise.allSettled([desktop.close(), mobile.close()])

after.content:
  await expect(page.getByRole("textbox", { name: "Message" })).toHaveValue("")
}

async function revokeDevice(context: BrowserContext, owner: Enrollment, deviceId: string,
  expectProjection: boolean) {
  const page = await context.newPage()
  try {
    await page.goto(`${webOrigin}/settings/relays/stage5/general`)
    const device = page.getByText(deviceId, { exact: true }).locator("..").locator("..")
    await expect(device).toBeVisible()
    const response = page.waitForResponse(value => value.request().method() === "DELETE"
      && new URL(value.url()).pathname === `/api/v1/devices/${encodeURIComponent(deviceId)}`)
    await device.getByRole("button", { name: "Revoke device" }).click()
    expect((await response).status()).toBe(200)
    if (expectProjection) await expect(device.getByText("Revoked", { exact: true })).toBeVisible()
  } finally {
    await page.close()
  }
